package derphttp

import (
	"fmt"
	"tailscale.com/derp"
)

// ConnectionError retains a real DERP connection failure and its phase. Only
// dial failures can represent positive endpoint unavailability; TLS and protocol
// failures remain terminal even when their cause resembles a network error.
type ConnectionError struct {
	Phase string
	Err   error
}

func (e *ConnectionError) Error() string            { return fmt.Sprintf("DERP %s: %v", e.Phase, e.Err) }
func (e *ConnectionError) Unwrap() error            { return e.Err }
func (e *ConnectionError) DERPFailurePhase() string { return e.Phase }

// ConnectionStateEvent is serialized under the client mutex. A nil Err means
// the server sent DERP ServerInfo, not merely that TCP or TLS connected.
type ConnectionStateEvent struct {
	Sequence uint64
	Err      error
}

func (c *Client) reportConnectionStateLocked(err error) {
	if c.OnConnectionState == nil {
		return
	}
	c.connectionStateSequence++
	c.OnConnectionState(ConnectionStateEvent{Sequence: c.connectionStateSequence, Err: err})
}

func (c *Client) connectionReady(client *derp.Client) {
	if c.OnConnectionState == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.client == client && !c.closed {
		c.reportConnectionStateLocked(nil)
	}
}

