func stateClient(t *testing.T, scheme string) (*Client, *[]ConnectionStateEvent) {
	t.Helper()
	c, err := NewClient(key.NewNode(), scheme+"://synthetic.invalid/derp", logger.Discard, netmon.NewStatic())
	if err != nil {
		t.Fatal(err)
	}
	events := new([]ConnectionStateEvent)
	c.OnConnectionState = func(e ConnectionStateEvent) { *events = append(*events, e) }
	t.Cleanup(func() { c.Close() })
	return c, events
}
func TestSobalinkDERPDialPreservesTypedJoinedErrors(t *testing.T) {
	unknown := errors.New("synthetic dial failure")
	for _, cause := range []error{syscall.ECONNREFUSED, syscall.EACCES, context.Canceled, context.DeadlineExceeded, unknown, errors.Join(syscall.ECONNREFUSED, unknown)} {
		c, events := stateClient(t, "https")
		c.SetURLDialer(func(context.Context, string, string) (net.Conn, error) { return nil, cause })
		err := c.Connect(context.Background())
		var staged *ConnectionError
		if !errors.As(err, &staged) || staged.DERPFailurePhase() != "dial" || !errors.Is(err, cause) {
			t.Fatalf("lost dial cause: %v", err)
		}
		if len(*events) != 1 || (*events)[0].Err != err || (*events)[0].Sequence != 1 {
			t.Fatal("missing ordered actual dial result")
		}
	}
}
func TestSobalinkDERPNilObserverRetainsUpstreamErrors(t *testing.T) {
	c, _ := stateClient(t, "https")
	c.OnConnectionState = nil
	c.SetURLDialer(func(context.Context, string, string) (net.Conn, error) { return nil, syscall.ECONNREFUSED })
	err := c.Connect(context.Background())
	var staged *ConnectionError
	if errors.As(err, &staged) || errors.Is(err, syscall.ECONNREFUSED) {
		t.Fatal("nil observer changed upstream behavior")
	}
}
func TestSobalinkDERPTLSAndAdmissionFailures(t *testing.T) {
	priv, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	template := &x509.Certificate{SerialNumber: big.NewInt(1), NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(time.Hour), DNSNames: []string{"synthetic.invalid"}, KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}}
	raw, err := x509.CreateCertificate(rand.Reader, template, template, &priv.PublicKey, priv)
	if err != nil {
		t.Fatal(err)
	}
	cert := tls.Certificate{Certificate: [][]byte{raw}, PrivateKey: priv}
	pin := errors.New("synthetic pin mismatch")
	for _, phase := range []string{"tls", "protocol"} {
		t.Run(phase, func(t *testing.T) {
			scheme := "https"
			if phase == "protocol" {
				scheme = "http"
			}
			c, events := stateClient(t, scheme)
			client, server := net.Pipe()
			t.Cleanup(func() { client.Close(); server.Close() })
			c.SetURLDialer(func(context.Context, string, string) (net.Conn, error) { return client, nil })
			done := make(chan struct{})
			go func() {
				defer close(done)
				defer server.Close()
				if phase == "tls" {
					tls.Server(server, &tls.Config{Certificates: []tls.Certificate{cert}}).Handshake()
					return
				}
				req, e := http.ReadRequest(bufio.NewReader(server))
				if e == nil {
					req.Body.Close()
					server.Write([]byte("HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n"))
				}
			}()
			if phase == "tls" {
				c.TLSConfig = &tls.Config{VerifyPeerCertificate: func([][]byte, [][]*x509.Certificate) error { return pin }}
			}
			ctx, cancel := context.WithTimeout(context.Background(), time.Second)
			defer cancel()
			err := c.Connect(ctx)
			var staged *ConnectionError
			if !errors.As(err, &staged) || staged.Phase != phase {
				t.Fatalf("wrong stage %v", err)
			}
			if phase == "tls" && !errors.Is(err, pin) {
				t.Fatal("pin rejection cause lost")
			}
			if len(*events) != 1 || (*events)[0].Err != err {
				t.Fatal("actual handshake failure not reported")
			}
			<-done
		})
	}
}
func TestSobalinkDERPJoinsAllNodeAndFamilyCauses(t *testing.T) {
	c, _ := stateClient(t, "https")
	c.UnderlayPolicy = derpGuardPolicy(t, "10.25.0.0/24", "10.25.0.2:443")
	both := &tailcfg.DERPNode{HostName: "synthetic.invalid", IPv4: "192.0.2.1", IPv6: "2001:db8::1"}
	_, err := c.dialNode(context.Background(), both)
	joined, ok := err.(interface{ Unwrap() []error })
	if !ok || len(joined.Unwrap()) != 2 {
		t.Fatal("family failures not retained", err)
	}
	disabled := &tailcfg.DERPNode{HostName: "synthetic.invalid", IPv4: "none", IPv6: "none"}
	_, _, err = c.dialRegion(context.Background(), &tailcfg.DERPRegion{Nodes: []*tailcfg.DERPNode{both, disabled}})
	joined, ok = err.(interface{ Unwrap() []error })
	if !ok || len(joined.Unwrap()) != 2 {
		t.Fatal("node failures not retained", err)
	}
}
func TestSobalinkDERPStaleClientCannotPublishSuccessOrFailure(t *testing.T) {
	c, events := stateClient(t, "https")
	old, current := new(derp.Client), new(derp.Client)
	c.client = current
	var wg sync.WaitGroup
	for range 8 {
		wg.Go(func() {
			for range 100 {
				c.connectionReady(old)
				c.closeForReconnect(old, syscall.ECONNRESET)
			}
		})
	}
	wg.Wait()
	if len(*events) != 0 {
		t.Fatal("retired client emitted state")
	}
	c.connectionReady(current)
	if len(*events) != 1 || (*events)[0].Err != nil {
		t.Fatal("current admission not reported")
	}
	c.closeForReconnect(current, syscall.ECONNRESET)
	if len(*events) != 2 {
		t.Fatal("current protocol failure missing")
	}
	var staged *ConnectionError
	if !errors.As((*events)[1].Err, &staged) || staged.Phase != "protocol" || !errors.Is(staged, syscall.ECONNRESET) {
		t.Fatal("protocol reset misclassified")
	}
}

