	cfg.Prefixes[0] = netip.MustParsePrefix("10.26.0.0/24")
	cfg.Relays[0] = netip.MustParseAddrPort("10.26.0.2:443")
	for _, address := range []string{"10.25.0.3:1", "[fd25::3]:65535"} {
		if err := p.DoUDP(netip.MustParseAddrPort(address), func() error { return nil }); err != nil {
			t.Fatal(address, err)
		}
	}
	for _, address := range []string{"10.26.0.3:443", "192.0.2.3:443", "8.8.8.8:443", "10.25.0.3:0", "[::ffff:10.25.0.3]:443", "[fd25::3%zone]:443", "[fd26::3]:443", "[ff02::1]:443"} {
		called := false
		err := p.DoUDP(netip.MustParseAddrPort(address), func() error { called = true; return nil })
		if !errors.Is(err, ErrDenied) || called {
			t.Fatalf("%s: error=%v called=%v", address, err, called)
		}
	}
	for _, prefix := range []string{"0.0.0.0/0", "10.25.0.1/24", "10.0.0.0/7", "172.0.0.0/8", "::/0", "fc00::/6", "::ffff:10.25.0.0/120"} {
		cfg := testConfig()
