func awaitRevoked(t *testing.T, p *Policy) {
	t.Helper()
	deadline := time.Now().Add(3 * time.Second)
	for !p.revoked.Load() {
		if time.Now().After(deadline) {
			t.Fatal("revocation did not start")
		}
		runtime.Gosched()
	}
}

func TestRevokeWaitsForAdmittedUDPAndDeniesRetries(t *testing.T) {
	p := testPolicy(t)
	entered, release, finished := make(chan struct{}), make(chan struct{}), make(chan struct{})
	go func() {
		defer close(finished)
		_ = p.DoUDP(netip.MustParseAddrPort("10.25.0.3:443"), func() error { close(entered); <-release; return nil })
	}()
	<-entered
	done := make(chan struct{})
	go func() { p.Revoke(); close(done) }()
	awaitRevoked(t, p)
	select {
	case <-done:
		t.Fatal("Revoke returned during write")
	default:
	}
	if err := p.DoUDP(netip.MustParseAddrPort("10.25.0.3:443"), func() error { t.Error("retry reached writer"); return nil }); !errors.Is(err, ErrRevoked) {
		t.Fatal(err)
	}
	close(release)
	<-finished
	<-done
	p.Revoke()
}

func TestTCPExactDestinationsAndFamilies(t *testing.T) {
	p := testPolicy(t)
	for _, tc := range []struct{ network, address string }{{"tcp", "relay.invalid:443"}, {"udp", "10.25.0.2:443"}, {"tcp4", "[fd25::2]:443"}, {"tcp6", "10.25.0.2:443"}, {"tcp", "10.25.0.2:444"}, {"tcp", "10.25.0.3:443"}, {"tcp", "[::ffff:10.25.0.2]:443"}, {"tcp", "[fd25::2%zone]:443"}} {
		_, err := p.DialContext(context.Background(), tc.network, tc.address, func(context.Context, string, string) (net.Conn, error) {
			t.Error("denied TCP reached dialer")
