		})
		if !errors.Is(err, ErrDenied) {
			t.Fatal(tc, err)
		}
	}
	for _, tc := range []struct{ network, address string }{{"tcp", "10.25.0.2:443"}, {"tcp4", "10.25.0.2:443"}, {"tcp6", "[fd25::2]:443"}} {
		left, right := net.Pipe()
