func TestRevokeClosesConnectionFromRacingDial(t *testing.T) {
	p := testPolicy(t)
	entered, release, finished := make(chan struct{}), make(chan struct{}), make(chan struct{})
	raw := &blockedConn{entered: make(chan struct{}), closed: make(chan struct{})}
	go func() {
		defer close(finished)
		c, err := p.DialContext(context.Background(), "tcp", "10.25.0.2:443", func(context.Context, string, string) (net.Conn, error) { close(entered); <-release; return raw, nil })
		if c != nil || !errors.Is(err, ErrRevoked) {
			t.Error(c, err)
		}
	}()
	<-entered
	done := make(chan struct{})
	go func() { p.Revoke(); close(done) }()
	awaitRevoked(t, p)
	select {
	case <-done:
		t.Fatal("pending dial not drained")
	default:
	}
	close(release)
	<-done
	<-finished
	if raw.closes.Load() != 1 {
		t.Fatal("racing connection leaked")
	}
}

type blockedConn struct {
	entered, closed chan struct{}
	once            sync.Once
	writes, closes  atomic.Int32
}

func (c *blockedConn) Write([]byte) (int, error) {
	c.writes.Add(1)
	close(c.entered)
	<-c.closed
	return 0, net.ErrClosed
}
func (c *blockedConn) Read([]byte) (int, error) { <-c.closed; return 0, net.ErrClosed }
func (c *blockedConn) Close() error {
	c.once.Do(func() { c.closes.Add(1); close(c.closed) })
	return nil
}
func (c *blockedConn) LocalAddr() net.Addr              { return &net.TCPAddr{} }
func (c *blockedConn) RemoteAddr() net.Addr             { return &net.TCPAddr{} }
func (c *blockedConn) SetDeadline(time.Time) error      { return nil }
func (c *blockedConn) SetReadDeadline(time.Time) error  { return nil }
func (c *blockedConn) SetWriteDeadline(time.Time) error { return nil }

