// DERPConnectionEvent reports the outcome of an existing DERP connection.
// Epoch increases when a region's client is replaced; Sequence orders outcomes
// within that client. The observer must discard retired/older epochs and stale
// sequences. Callbacks must not block or call into magicsock or derphttp.
// Sequence zero starts a new epoch. Nil Err at a positive Sequence confirms
// DERP ServerInfo. Retired ends the epoch, including any late in-flight callback.
type DERPConnectionEvent struct {
	RegionID tailcfg.DERPRegionID
	Epoch    uint64
	Sequence uint64
	Retired  bool
	Err      error
}

