package magicsock

import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/netip"
	"slices"

	"tailscale.com/feature/buildfeatures"
	"tailscale.com/net/netcheck"
	"tailscale.com/tailcfg"
)

// WANConfig is immutable, explicit opt-in address discovery. It never replaces
// the separately configured DERP map or supplies relay certificates.
const wanSTUNRegionNamespaceSize = 1<<16 - 1
const defaultWANProbeBudget = 4

// ProbeBudget is a finite, adjustable resource budget: destinations per report.
// Zero selects the default; it never limits the configured metadata to four.
type WANConfig struct {
	ProbeBudget   int
	STUNEndpoints []netip.AddrPort
	AdvertiseIPv6 bool
}

// ValidateWANConfig validates before any subsystem or socket is created. Nil
// retains the original engine behavior. Restricted engines reject this feature.
func ValidateWANConfig(config *WANConfig, restricted bool) (*WANConfig, error) {
	if config == nil {
		return nil, nil
	}
	if restricted || !buildfeatures.HasUDPTransport || !buildfeatures.HasNATTraversal || buildfeatures.HasPortMapper || buildfeatures.HasCaptivePortal || buildfeatures.HasUseProxy {
		return nil, errors.New("WAN candidates require unrestricted UDP transport without port mapping, captive portal or proxy features")
	}
	if len(config.STUNEndpoints) > wanSTUNRegionNamespaceSize || config.ProbeBudget < 0 || config.ProbeBudget > wanSTUNRegionNamespaceSize || len(config.STUNEndpoints) == 0 && !config.AdvertiseIPv6 {
		return nil, errors.New("explicit bounded WAN candidates required")
	}
	out := &WANConfig{STUNEndpoints: slices.Clone(config.STUNEndpoints), AdvertiseIPv6: config.AdvertiseIPv6, ProbeBudget: config.ProbeBudget}
	if out.ProbeBudget == 0 {
		out.ProbeBudget = defaultWANProbeBudget
	}
	for _, ep := range out.STUNEndpoints {
		ip := ep.Addr()
		if !ep.IsValid() || ep.Port() == 0 || ip.Is4In6() || ip.Zone() != "" || (!ip.IsGlobalUnicast() && !ip.IsLoopback()) {
			return nil, errors.New("WAN STUN destinations must be numeric unicast endpoints")
		}
	}
	slices.SortFunc(out.STUNEndpoints, func(a, b netip.AddrPort) int { return a.Compare(b) })
	for i := 1; i < len(out.STUNEndpoints); i++ {
		if out.STUNEndpoints[i] == out.STUNEndpoints[i-1] {
			return nil, errors.New("duplicate WAN STUN destination")
		}
	}
	return out, nil
}

// wanSTUNBatch is an immutable bounded selection, private to netcheck. Stable
// IDs are drawn from the nonzero 16-bit namespace, never from the relay map.
// The exact writer gate admits only this batch, not all stored metadata.
type wanSTUNBatch struct {
	dm           *tailcfg.DERPMap
	destinations map[netip.AddrPort]struct{}
	hasIPv4      bool
}

func wanSTUNMap(config *WANConfig, start int) (*wanSTUNBatch, int) {
	if config == nil {
		return nil, 0
	}
	dm := &tailcfg.DERPMap{OmitDefaultRegions: true, Regions: map[tailcfg.DERPRegionID]*tailcfg.DERPRegion{}}
	batch := &wanSTUNBatch{dm: dm, destinations: map[netip.AddrPort]struct{}{}}
	n := len(config.STUNEndpoints)
	if n == 0 {
		return batch, 0
	}
	budget := config.ProbeBudget
	if budget == 0 {
		budget = defaultWANProbeBudget
	}
	// Configurations are validated before construction. Fail closed defensively
	// if this pure selector is ever called directly with an invalid budget.
	if budget < 1 || budget > wanSTUNRegionNamespaceSize || n > wanSTUNRegionNamespaceSize {
		return batch, 0
	}
	start = ((start % n) + n) % n
	count := min(n, budget)
	for offset := 0; offset < count; offset++ {
		i := (start + offset) % n
		ep := config.STUNEndpoints[i]
		id := tailcfg.DERPRegionID(i + 1)
		node := &tailcfg.DERPNode{Name: fmt.Sprintf("wan-stun-%d", i), RegionID: id, HostName: ep.Addr().String(), IPv4: "none", IPv6: "none", STUNPort: int(ep.Port()), STUNOnly: true, DERPPort: -1}
		if ep.Addr().Is4() {
			node.IPv4 = ep.Addr().String()
			batch.hasIPv4 = true
		} else {
			node.IPv6 = ep.Addr().String()
		}
		dm.Regions[id] = &tailcfg.DERPRegion{RegionID: id, Nodes: []*tailcfg.DERPNode{node}}
		batch.destinations[ep] = struct{}{}
	}
	return batch, (start + count) % n
}

func (c *Conn) nextWANSTUNBatch() *wanSTUNBatch {
	c.mu.Lock()
	defer c.mu.Unlock()
	batch, next := wanSTUNMap(c.wanCandidates, c.wanSTUNCursor)
	c.wanSTUNCursor = next
	c.wanSTUNSelection.Store(batch)
	return batch
}

func (c *Conn) wanAllowsSTUN(destination netip.AddrPort) bool {
	if c.wanCandidates == nil {
		return true
	}
	batch := c.wanSTUNSelection.Load()
	if batch == nil {
		return false
	}
	_, allowed := batch.destinations[destination]
	return allowed
}

// A discovery service has no authority to select a relay. Clone because netcheck
// retains the original report for scheduling its own bounded next probe plan.
func wanCandidateReport(report *netcheck.Report) *netcheck.Report {
	report = report.Clone()
	report.PreferredDERP = 0
	report.RegionLatency = nil
	report.RegionV4Latency = nil
	report.RegionV6Latency = nil
	return report
}

// wanLocalEndpoint uses the actual v6 socket rather than assuming that v4 and
// v6 bound the same port. A missing/disabled v6 socket advertises no v6 endpoint.
// netmon already excludes down and problematic interfaces and limits addresses.
func wanLocalEndpoint(ip netip.Addr, port4 uint16, local6 *net.UDPAddr) (netip.AddrPort, bool) {
	if ip.Is6() && !ip.IsGlobalUnicast() {
		return netip.AddrPort{}, false
	}
	return localSocketEndpoint(ip, port4, local6)
}

// localSocketEndpoint also permits loopback for strict LAN and native fixtures.
// It never substitutes the IPv4 port for an absent or independently bound IPv6 socket.
func localSocketEndpoint(ip netip.Addr, port4 uint16, local6 *net.UDPAddr) (netip.AddrPort, bool) {
	if ip.Is4() {
		return netip.AddrPortFrom(ip, port4), port4 != 0
	}
	if !ip.Is6() || ip.Is4In6() || ip.Zone() != "" || (!ip.IsGlobalUnicast() && !ip.IsLoopback()) || local6 == nil || local6.Port < 1 || local6.Port > 65535 {
		return netip.AddrPort{}, false
	}
	bound := local6.AddrPort().Addr()
	if !bound.Is6() || !bound.IsUnspecified() && bound != ip {
		return netip.AddrPort{}, false
	}
	return netip.AddrPortFrom(ip, uint16(local6.Port)), true
}

// Opt-in WAN discovery contacts only the configured STUN destinations. Cloud
// metadata is not a selected discovery service. Nil retains upstream behavior.
func (c *Conn) candidateCloudIPs(ctx context.Context) ([]netip.Addr, error) {
	if c.wanCandidates != nil {
		return nil, nil
	}
	return c.cloudInfo.GetPublicIPs(ctx)
}

