func TestWANCandidateProbeBudgetRotatesWithoutMetadataCap(t *testing.T) {
	requireWANBuild(t)
	var endpoints []netip.AddrPort
	for port := uint16(30000); port < 30011; port++ {
		endpoints = append(endpoints, netip.AddrPortFrom(netip.MustParseAddr("192.0.2.1"), port))
	}
	for _, budget := range []int{0, 1, 3, 7, 20} {
		config, err := ValidateWANConfig(&WANConfig{STUNEndpoints: endpoints, ProbeBudget: budget}, false)
		if err != nil {
			t.Fatal("configurable metadata was capped", err)
		}
		if budget == 0 {
			budget = defaultWANProbeBudget
		}
		if config.ProbeBudget != budget || len(config.STUNEndpoints) != len(endpoints) {
			t.Fatal("configuration lost metadata or budget")
		}
		c := &Conn{wanCandidates: config}
		seen := map[netip.AddrPort]bool{}
		for range len(endpoints) {
			batch := c.nextWANSTUNBatch()
			if len(batch.dm.Regions) != min(budget, len(endpoints)) || len(batch.destinations) != len(batch.dm.Regions) {
				t.Fatal("probe fanout exceeded selected resource budget")
			}
			for i, ep := range endpoints {
				_, selected := batch.destinations[ep]
				if c.wanAllowsSTUN(ep) != selected {
					t.Fatal("writer authority exceeded current batch")
				}
				if selected {
					seen[ep] = true
					region := batch.dm.Regions[tailcfg.DERPRegionID(i+1)]
					if region == nil || region.Nodes[0].STUNPort != int(ep.Port()) {
						t.Fatal("rotation changed stable discovery identity")
					}
				}
			}
		}
		if len(seen) != len(endpoints) {
			t.Fatal("rotating selection starved configured metadata")
		}
		if !reflect.DeepEqual(config.STUNEndpoints, endpoints) {
			t.Fatal("rotation mutated metadata")
		}
	}
}

