type guardedFakeUDP struct {
	*blockForeverConn
	writes  int
	onWrite func() error
}

func (f *guardedFakeUDP) WriteToUDPAddrPort(b []byte, _ netip.AddrPort) (int, error) {
	f.writes++
	if f.onWrite != nil {
		return 0, f.onWrite()
	}
	return len(b), nil
}
func (f *guardedFakeUDP) ReadFrom(b []byte) (int, net.Addr, error) {
	n, ap, e := f.ReadFromUDPAddrPort(b)
	return n, net.UDPAddrFromAddrPort(ap), e
}
func (f *guardedFakeUDP) WriteTo(b []byte, a net.Addr) (int, error) {
	return f.WriteToUDPAddrPort(b, a.(*net.UDPAddr).AddrPort())
}

type guardedFakeBatch struct {
	guardedFakeUDP
	batches int
	onBatch func() error
}

func (f *guardedFakeBatch) ReadBatch([]byte, []batching.ReceivedPacket) (int, error) {
	return 0, net.ErrClosed
}
func (f *guardedFakeBatch) WriteBatchTo([][]byte, netip.AddrPort, packet.GeneveHeader, int) error {
	f.batches++
	if f.onBatch != nil {
		return f.onBatch()
	}
	return nil
}

var _ batching.Conn = (*guardedFakeBatch)(nil)

func newGuardedPolicy(t *testing.T, prefix, relay string) *underlayguard.Policy {
	t.Helper()
	p, e := underlayguard.New(underlayguard.Config{Prefixes: []netip.Prefix{netip.MustParsePrefix(prefix)}, Relays: []netip.AddrPort{netip.MustParseAddrPort(relay)}})
	if e != nil {
		t.Fatal(e)
	}
	t.Cleanup(p.Revoke)
	return p
}
func guardedSet(c *RebindingUDPConn, p nettype.PacketConn) { c.pconn = p; c.pconnAtomic.Store(&p) }
func guardedBuffers() [][]byte {
	return [][]byte{append(make([]byte, packet.GeneveFixedHeaderLength), []byte("synthetic-one")...), append(make([]byte, packet.GeneveFixedHeaderLength), []byte("synthetic-two")...)}
}
func guardedFakeConn(p nettype.PacketConn, policy *underlayguard.Policy) *Conn {
	c := newConn(logger.Discard)
	c.underlayPolicy = policy
	c.metrics = registerMetrics(new(usermetric.Registry))
	c.pconn4.underlayPolicy = policy
	c.pconn6.underlayPolicy = policy
	guardedSet(&c.pconn4, p)
	guardedSet(&c.pconn6, p)
	return c
}
func guardedCalls(c *Conn, ap netip.AddrPort) []func() error {
	return []func() error{
		func() error { _, e := c.sendUDPStd(ap, []byte("synthetic")); return e },
		func() error { _, e := c.sendUDP(ap, []byte("synthetic-disco"), true, false); return e },
		func() error { _, e := c.sendUDPNetcheck([]byte("synthetic-netcheck"), ap); return e },
		func() error {
			_, e := c.sendUDPBatch(epAddr{ap: ap}, guardedBuffers(), packet.GeneveFixedHeaderLength)
			return e
		},
		func() error {
			return c.Send(guardedBuffers(), &lazyEndpoint{c: c, src: epAddr{ap: ap}}, packet.GeneveFixedHeaderLength)
		},
	}
}

func TestUnderlayGuardFakeUDPBoundaries(t *testing.T) {
	for _, family := range []struct {
		prefix, relay string
		addresses     []string
	}{
		{"10.25.0.0/24", "10.25.0.2:443", []string{"10.25.0.3:3000", "10.26.0.3:3000", "192.0.2.3:3000", "[::ffff:10.25.0.3]:3000"}},
		{"fd25::/64", "[fd25::2]:443", []string{"[fd25::3]:3000", "[fd26::3]:3000", "[2001:db8::3]:3000", "[fd25::3%fixture]:3000"}},
	} {
		for _, fast := range []bool{false, true} {
			for i, address := range family.addresses {
				policy := newGuardedPolicy(t, family.prefix, family.relay)
				single := &guardedFakeUDP{blockForeverConn: newBlockForeverConn()}
				batch := &guardedFakeBatch{guardedFakeUDP: guardedFakeUDP{blockForeverConn: newBlockForeverConn()}}
				var p nettype.PacketConn = single
				if fast {
					p = batch
				}
				c := guardedFakeConn(p, policy)
				for _, call := range guardedCalls(c, netip.MustParseAddrPort(address)) {
					err := call()
					if i == 0 {
						if err != nil {
							t.Fatal(err)
						}
					} else if !errors.Is(err, underlayguard.ErrDenied) {
						t.Fatal("denied UDP did not fail closed", err)
					}
				}
				if i != 0 && (single.writes != 0 || batch.writes != 0 || batch.batches != 0) {
					t.Fatal("denied destination reached actual writer")
				}
			}
		}
	}
}

func TestUnderlayGuardFakeRetryRevocation(t *testing.T) {
	for _, fast := range []bool{false, true} {
		policy := newGuardedPolicy(t, "10.25.0.0/24", "10.25.0.2:443")
		first := &guardedFakeBatch{}
		next := &guardedFakeBatch{}
		c := guardedFakeConn(first, policy)
		revoked := make(chan struct{})
		revoke := func() error {
			guardedSet(&c.pconn4, next)
			go func() { policy.Revoke(); close(revoked) }()
			deadline := time.Now().Add(time.Second)
			for !errors.Is(policy.Validate(), underlayguard.ErrRevoked) {
				if time.Now().After(deadline) {
					t.Fatal("revocation not started")
				}
				runtime.Gosched()
			}
			return net.ErrClosed
		}
		first.onWrite = revoke
		first.onBatch = revoke
		ap := netip.MustParseAddrPort("10.25.0.3:3000")
		var err error
		if fast {
			err = c.pconn4.WriteWireGuardBatchTo(guardedBuffers(), epAddr{ap: ap}, packet.GeneveFixedHeaderLength)
		} else {
			_, err = c.pconn4.WriteToUDPAddrPort(nil, ap)
		}
		<-revoked
		if !errors.Is(err, underlayguard.ErrRevoked) || next.writes != 0 || next.batches != 0 {
			t.Fatal("retry escaped revoked policy", err)
		}
	}
}

func TestUnderlayGuardFakeNilMode(t *testing.T) {
	f := &guardedFakeBatch{}
	c := guardedFakeConn(f, nil)
	for _, call := range guardedCalls(c, netip.MustParseAddrPort("192.0.2.3:3000")) {
		if err := call(); err != nil {
			t.Fatal(err)
		}
	}
	if f.writes != 3 || f.batches != 2 {
		t.Fatal(f.writes, f.batches)
	}
}

