	bus := eventbus.New()
	defer bus.Close()
	c, err := NewConn(Options{UnderlayPolicy: policy, EventBus: bus, NetMon: netmon.NewStatic(), Logf: logger.Discard, HealthTracker: health.NewTracker(bus), Metrics: new(usermetric.Registry), TestOnlyPacketListener: guardedListener{}})
	if err != nil {
		t.Fatal(err)
	}
	defer c.Close()
	if c.underlayPolicy != policy || c.pconn4.underlayPolicy != policy || c.pconn6.underlayPolicy != policy || c.netChecker.UnderlayPolicy != policy {
		t.Fatal("constructor omitted policy")
	}
	if c.portMapper != nil || c.getPinger() != nil {
		t.Fatal("guarded engine created diagnostics")
	}
	if _, err = c.updateNetInfo(context.Background()); err != nil {
		t.Fatal("diagnostic suppression broke local endpoint refresh", err)
	}
	for _, call := range guardedCalls(c, netip.MustParseAddrPort("192.0.2.3:3000")) {
		if !errors.Is(call(), underlayguard.ErrDenied) {
			t.Fatal("constructor writer unguarded")
		}
	}
	// Construct the actual lazy DERP client with its context already cancelled,
	// so this pointer-propagation assertion can never initiate a network dial.
	c.connCtxCancel()
	c.mu.Lock()
	c.privateKey = key.NewNode()
	c.derpMap = &tailcfg.DERPMap{Regions: map[tailcfg.DERPRegionID]*tailcfg.DERPRegion{1: {RegionID: 1}}}
	c.derpMapAtomic.Store(c.derpMap)
	c.mu.Unlock()
	if c.derpWriteChanForRegion(1, key.NodePublic{}) == nil {
		t.Fatal("DERP constructor not reached")
	}
	c.mu.Lock()
	dc := c.activeDerp[1].c
	c.mu.Unlock()
	if dc == nil || dc.UnderlayPolicy != policy {
		t.Fatal("DERP constructor omitted policy")
	}

}

func TestUnderlayGuardNativeLoopbackUDP(t *testing.T) {
	if os.Getenv("SOBALINK_RUN_UNDERLAY_NATIVE") != "1" {
		t.Skip("explicit native loopback opt-in required")
	}
	for _, family := range []struct{ network, address, prefix, relay string }{{"udp4", "127.0.0.1:0", "127.0.0.1/32", "127.0.0.1:443"}, {"udp6", "[::1]:0", "::1/128", "[::1]:443"}} {
		t.Run(family.network, func(t *testing.T) {
			receiver, err := net.ListenUDP(family.network, net.UDPAddrFromAddrPort(netip.MustParseAddrPort(family.address)))
			if err != nil {
				t.Fatal(err)
			}
			defer receiver.Close()
			sender, err := net.ListenUDP(family.network, net.UDPAddrFromAddrPort(netip.MustParseAddrPort(family.address)))
			if err != nil {
				t.Fatal(err)
			}
			defer sender.Close()
			p := newGuardedPolicy(t, family.prefix, family.relay)
			c := guardedFakeConn(sender, p)
			ruc := &c.pconn4
			if family.network == "udp6" {
				ruc = &c.pconn6
			}
			ruc.setConnLocked(sender, family.network, nil)
			ap := receiver.LocalAddr().(*net.UDPAddr).AddrPort()
			for i, call := range guardedCalls(c, ap) {
				if err := call(); err != nil {
					t.Fatal(i, err)
				}
				count := 1
				if i >= 3 {
					count = 2
				}
				for j := 0; j < count; j++ {
					receiver.SetReadDeadline(time.Now().Add(time.Second))
					if n, _, err := receiver.ReadFromUDPAddrPort(make([]byte, 256)); err != nil || n == 0 {
						t.Fatal(i, j, n, err)
					}
				}
			}
			// The same receiver already proved it can receive. A separate
			// immutable policy excludes it, without requiring a loopback alias.
			deniedPolicy := newGuardedPolicy(t, "10.25.0.0/24", "10.25.0.2:443")
			deniedSender, err := net.ListenUDP(family.network, net.UDPAddrFromAddrPort(netip.MustParseAddrPort(family.address)))
			if err != nil {
				t.Fatal(err)
			}
			defer deniedSender.Close()
			deniedConn := guardedFakeConn(deniedSender, deniedPolicy)
			for _, call := range guardedCalls(deniedConn, ap) {
				if !errors.Is(call(), underlayguard.ErrDenied) {
					t.Fatal("unselected native destination admitted")
				}
			}
			receiver.SetReadDeadline(time.Now().Add(50 * time.Millisecond))
			if _, _, err := receiver.ReadFromUDPAddrPort(make([]byte, 256)); err == nil {
				t.Fatal("unselected native receiver got a packet")
			} else if ne, ok := err.(net.Error); !ok || !ne.Timeout() {
				t.Fatal("negative UDP receiver did not time out", err)
			}
			p.Revoke()
			if _, err := sender.WriteToUDPAddrPort([]byte("revoked-raw-socket"), ap); !errors.Is(err, net.ErrClosed) {
				t.Fatal("revoke did not close actual UDP socket", err)
			}
			for _, call := range guardedCalls(c, ap) {
				if !errors.Is(call(), underlayguard.ErrRevoked) {
					t.Fatal("revoked native writer admitted")
				}
			}
			receiver.SetReadDeadline(time.Now().Add(50 * time.Millisecond))
			if _, _, err := receiver.ReadFromUDPAddrPort(make([]byte, 256)); err == nil {
				t.Fatal("post-revocation packet received")
			} else if ne, ok := err.(net.Error); !ok || !ne.Timeout() {
				t.Fatal("revoked UDP receiver did not time out", err)
			}
		})
	}
}

